public class PiiEntitiesDetectionJobFactory(string resourceName = null, Action<Humidifier.Comprehend.PiiEntitiesDetectionJob> factoryAction = null) : ResourceFactory<Humidifier.Comprehend.PiiEntitiesDetectionJob>(resourceName)
{

    internal List<InnerPiiEntitiesDetectionJobTagsItemsFactory> TagsFactories { get; set; } = [];

    internal InnerPiiEntitiesDetectionJobRedactionConfigFactory RedactionConfigFactory { get; set; }

    internal InnerPiiEntitiesDetectionJobInputDataConfigFactory InputDataConfigFactory { get; set; }

    protected override Humidifier.Comprehend.PiiEntitiesDetectionJob Create()
    {
        var piiEntitiesDetectionJobResult = CreatePiiEntitiesDetectionJob();
        factoryAction?.Invoke(piiEntitiesDetectionJobResult);

        return piiEntitiesDetectionJobResult;
    }

    private Humidifier.Comprehend.PiiEntitiesDetectionJob CreatePiiEntitiesDetectionJob()
    {
        var piiEntitiesDetectionJobResult = new Humidifier.Comprehend.PiiEntitiesDetectionJob
        {
            GivenName = InputResourceName,
        };

        return piiEntitiesDetectionJobResult;
    }
    public override void CreateChildren(Humidifier.Comprehend.PiiEntitiesDetectionJob result)
    {
        base.CreateChildren(result);

        result.Tags = TagsFactories.Any() ? TagsFactories.Select(x => x.Build()).ToList() : null;
        result.RedactionConfig ??= RedactionConfigFactory?.Build();
        result.InputDataConfig ??= InputDataConfigFactory?.Build();
    }

} // End Of Class

